import{_ as e,C as i,c as a,o as t,a0 as n,b as r,w as o,a as l,G as s,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Communication d&#39;équipe","description":"","frontmatter":{},"headers":[],"relativePath":"fr/education/team-player/communication.md","filePath":"fr/education/team-player/communication.md"}');const d=e({name:"fr/education/team-player/communication.md"},[["render",function(e,c,d,p,m,h){const q=i("Mermaid");return t(),a("div",null,[c[1]||(c[1]=n('<h1 id="communication-d-39-equipe" tabindex="-1">Communication d&#39;équipe <a class="header-anchor" href="#communication-d-39-equipe" aria-label="Permalink to &quot;Communication d&amp;#39;équipe&quot;">​</a></h1><p>Une communication efficace transforme un groupe d&#39;individus en une équipe. À la pétanque, où la stratégie évolue constamment et où la pression est forte, la qualité de votre communication peut déterminer l&#39;issue du jeu.</p><div class="tip custom-block"><p class="custom-block-title">La grande idée</p><p><strong>La communication est ce qui transforme les individus en une équipe.</strong> Une communication claire, précise et encourageante, même sous pression, distingue les bonnes équipes des excellentes équipes.</p></div><h2 id="le-cycle-de-communication" tabindex="-1">Le cycle de communication <a class="header-anchor" href="#le-cycle-de-communication" aria-label="Permalink to &quot;Le cycle de communication&quot;">​</a></h2><p>Une bonne communication au sein d&#39;une équipe suit un cycle :</p>',5)),(t(),r(u,null,{default:o(()=>[s(q,{id:"mermaid-17",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObserver%5D%20--%3E%20B%5BPartager%5D%0A%20%20%20%20B%20--%3E%20C%5BDiscuter%5D%0A%20%20%20%20C%20--%3E%20D%5BD%C3%A9cider%5D%0A%20%20%20%20D%20--%3E%20E%5BEx%C3%A9cuter%5D%0A%20%20%20%20E%20--%3E%20F%5BRevoir%5D%0A%20%20%20%20F%20--%3E%20A%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23f3e5f5%0A"})]),fallback:o(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[2]||(c[2]=n('<table tabindex="0"><thead><tr><th>Étape</th><th>Action</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Observer</strong></td><td>Remarquez ce qui se passe</td><td>Terrain, positions, adversaires</td></tr><tr><td><strong>Partager</strong></td><td>Signalez ce que vous voyez à vos coéquipiers.</td><td>« Le terrain est en pente à gauche. »</td></tr><tr><td><strong>Discuter</strong></td><td>Perspectives d&#39;échange</td><td>« Dois-je bloquer ou tenter de marquer ? »</td></tr><tr><td><strong>Décider</strong></td><td>Se mettre d&#39;accord sur l&#39;approche</td><td>&quot;Essayons le lob haut&quot;</td></tr><tr><td><strong>Exécuter</strong></td><td>Faites-le avec engagement</td><td>Concentrez-vous pleinement sur le lancer</td></tr><tr><td><strong>Revoir</strong></td><td>Tirer les leçons des résultats</td><td>« Ça a bien fonctionné » ou « La prochaine fois… »</td></tr></tbody></table><h2 id="quand-communiquer" tabindex="-1">Quand communiquer <a class="header-anchor" href="#quand-communiquer" aria-label="Permalink to &quot;Quand communiquer&quot;">​</a></h2><h3 id="avant-chaque-extremite" tabindex="-1">Avant chaque extrémité <a class="header-anchor" href="#avant-chaque-extremite" aria-label="Permalink to &quot;Avant chaque extrémité&quot;">​</a></h3><ul><li>Évaluer le terrain ensemble</li><li>Discuter de l&#39;approche générale</li><li>Précisez qui lance et quand.</li><li>Donner le ton (calme, concentré)</li></ul><h3 id="pendant-la-fin" tabindex="-1">Pendant la fin <a class="header-anchor" href="#pendant-la-fin" aria-label="Permalink to &quot;Pendant la fin&quot;">​</a></h3><ul><li>Partager les observations (« Le terrain est en pente à gauche »)</li><li>Stratégie de coordination (« Dois-je essayer de bloquer ou de marquer ? »)</li><li>Offrez votre soutien (« Prends ton temps, tu peux le faire »)</li><li>Adaptez vos plans en fonction de l&#39;évolution de la situation.</li></ul><h3 id="entre-les-extremites" tabindex="-1">Entre les extrémités <a class="header-anchor" href="#entre-les-extremites" aria-label="Permalink to &quot;Entre les extrémités&quot;">​</a></h3><ul><li>Débriefing rapide (ce qui a fonctionné, ce qui n&#39;a pas fonctionné)</li><li>Se réinitialiser mentalement</li><li>Préparez-vous pour la prochaine fin</li><li>Restez connectés en équipe</li></ul><h3 id="apres-le-match" tabindex="-1">Après le match <a class="header-anchor" href="#apres-le-match" aria-label="Permalink to &quot;Après le match&quot;">​</a></h3><ul><li>Débriefing complet (le cas échéant)</li><li>Reconnaître les contributions</li><li>Identifier les enseignements</li><li>Maintenir les relations</li></ul><h2 id="comment-communiquer" tabindex="-1">Comment communiquer <a class="header-anchor" href="#comment-communiquer" aria-label="Permalink to &quot;Comment communiquer&quot;">​</a></h2><h3 id="soyez-clair-et-precis" tabindex="-1">Soyez clair et précis <a class="header-anchor" href="#soyez-clair-et-precis" aria-label="Permalink to &quot;Soyez clair et précis&quot;">​</a></h3><p><strong>Vague :</strong> « Essayez de vous rapprocher » <strong>Précisions :</strong> « Visez le côté gauche du cric, à environ 20 cm de distance. »</p><p><strong>Vague :</strong> « Bien essayé » <strong>Clair :</strong> « Bon poids, juste un peu à gauche de la ligne »</p><h3 id="soyez-constructif" tabindex="-1">Soyez constructif <a class="header-anchor" href="#soyez-constructif" aria-label="Permalink to &quot;Soyez constructif&quot;">​</a></h3><p>Concentrez-vous sur les solutions, pas sur les problèmes :</p><p><strong>Axé sur le problème :</strong> « Tu rates toujours tes tirs à droite. » <strong>Axé sur la solution :</strong> « Peut-être essayer de viser un peu plus à gauche pour compenser ? »</p><h3 id="soyez-solidaire" tabindex="-1">Soyez solidaire <a class="header-anchor" href="#soyez-solidaire" aria-label="Permalink to &quot;Soyez solidaire&quot;">​</a></h3><p>Votre ton compte autant que vos mots :</p><ul><li>Gardez votre calme, même en cas de frustration.</li><li>Utilisez un langage corporel encourageant</li><li>Reconnaissez les efforts, pas seulement les résultats.</li><li>Construisez, ne détruisez pas</li></ul><h3 id="ecoutez-activement" tabindex="-1">Écoutez activement <a class="header-anchor" href="#ecoutez-activement" aria-label="Permalink to &quot;Écoutez activement&quot;">​</a></h3><p>La communication est bidirectionnelle :</p><ul><li>Soyez pleinement attentif lorsque vos coéquipiers parlent.</li><li>Posez des questions de clarification</li><li>Accusez réception de ce que vous avez entendu</li><li>N&#39;interrompez pas et ne rejetez pas</li></ul><h2 id="defis-de-communication" tabindex="-1">Défis de communication <a class="header-anchor" href="#defis-de-communication" aria-label="Permalink to &quot;Défis de communication&quot;">​</a></h2><h3 id="desaccord-sur-la-strategie" tabindex="-1">Désaccord sur la stratégie <a class="header-anchor" href="#desaccord-sur-la-strategie" aria-label="Permalink to &quot;Désaccord sur la stratégie&quot;">​</a></h3><p><strong>Mauvaise approche :</strong></p><ul><li>Insistez pour suivre votre chemin</li><li>Adoptez une position défensive</li><li>Céder avec ressentiment</li><li>Discutez pendant le jeu</li></ul><p><strong>Meilleure approche :</strong></p><ol><li>Exprimez clairement votre point de vue</li><li>Écoutez-les en entier</li><li>Discutez brièvement des avantages et des inconvénients.</li><li>Décidez ensemble (ou reportez-vous au responsable désigné).</li><li>Engagez-vous pleinement dans cette décision.</li><li>Analyse après le match</li></ol><h3 id="suite-a-une-erreur-d-39-un-coequipier" tabindex="-1">Suite à une erreur d&#39;un coéquipier <a class="header-anchor" href="#suite-a-une-erreur-d-39-un-coequipier" aria-label="Permalink to &quot;Suite à une erreur d&amp;#39;un coéquipier&quot;">​</a></h3><p><strong>Ce dont ils ont besoin :</strong></p><ul><li>Accusé de réception rapide</li><li>Autorisation de passer à autre chose</li><li>La confiance que vous leur faites encore confiance</li><li>Concentrez-vous sur le prochain lancer</li></ul><p><strong>Que dire :</strong></p><ul><li>« Pas de problème, le suivant »</li><li>«Dur à toi, la suite t&#39;attend.»</li><li>«Nous sommes toujours dans le coup»</li><li><em>Parfois, un simple signe de tête ou une tape suffit.</em></li></ul><p><strong>Ce qu&#39;il ne faut PAS dire :</strong></p><ul><li>Rien (le silence sonne comme un jugement)</li><li>&quot;Ça va&quot; (peut paraître dédaigneux)</li><li>Tout ce qui a mal tourné (pas maintenant)</li><li>Frustration visible (le langage corporel compte)</li></ul><h3 id="quand-vous-faites-une-erreur" tabindex="-1">Quand vous faites une erreur <a class="header-anchor" href="#quand-vous-faites-une-erreur" aria-label="Permalink to &quot;Quand vous faites une erreur&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire:</strong></p><ul><li>Bref aveu (« Toutes mes excuses »)</li><li>Ne vous excusez pas excessivement.</li><li>Ne cherchez pas d&#39;excuses.</li><li>Réinitialisez-vous et concentrez-vous sur le prochain lancer.</li><li>Ayez confiance en vos coéquipiers pour vous soutenir.</li></ul><h3 id="tensions-au-sein-de-l-39-equipe" tabindex="-1">Tensions au sein de l&#39;équipe <a class="header-anchor" href="#tensions-au-sein-de-l-39-equipe" aria-label="Permalink to &quot;Tensions au sein de l&amp;#39;équipe&quot;">​</a></h3><p>Si la tension monte pendant un match :</p><ol><li>Prenez conscience que cela se produit.</li><li>Respirez profondément avant de répondre.</li><li>Concentrez-vous sur le jeu, pas sur le conflit.</li><li>Abordez le sujet correctement après le match.</li><li>Ne laissez pas cela affecter votre jeu</li></ol><h2 id="communication-non-verbale" tabindex="-1">Communication non verbale <a class="header-anchor" href="#communication-non-verbale" aria-label="Permalink to &quot;Communication non verbale&quot;">​</a></h2><p>Une grande partie de la communication au sein d&#39;une équipe est non verbale :</p><h3 id="signaux-positifs" tabindex="-1">Signaux positifs <a class="header-anchor" href="#signaux-positifs" aria-label="Permalink to &quot;Signaux positifs&quot;">​</a></h3><ul><li>contact visuel</li><li>Hochement de tête</li><li>J&#39;approuve</li><li>Posture détendue</li><li>Se rapprocher des coéquipiers</li><li>Sourire (le cas échéant)</li></ul><h3 id="signaux-negatifs-a-eviter" tabindex="-1">Signaux négatifs (à éviter) <a class="header-anchor" href="#signaux-negatifs-a-eviter" aria-label="Permalink to &quot;Signaux négatifs (à éviter)&quot;">​</a></h3><ul><li>Levant les yeux au ciel</li><li>Se détournant</li><li>Bras croisés</li><li>Soupirs</li><li>Secouant la tête</li><li>langage corporel tendu</li></ul><p><strong>N&#39;oubliez pas :</strong> Vos coéquipiers voient tout. Votre langage corporel influence leur confiance et leurs performances.</p><h2 id="developper-des-habitudes-de-communication" tabindex="-1">Développer des habitudes de communication <a class="header-anchor" href="#developper-des-habitudes-de-communication" aria-label="Permalink to &quot;Développer des habitudes de communication&quot;">​</a></h2><h3 id="pratiquer-la-communication" tabindex="-1">Pratiquer la communication <a class="header-anchor" href="#pratiquer-la-communication" aria-label="Permalink to &quot;Pratiquer la communication&quot;">​</a></h3><p>N’attendez pas que la concurrence communique :</p><ul><li>Pratiquer les discussions stratégiques en formation</li><li>Donnez-vous régulièrement des retours constructifs.</li><li>Développez le langage de votre équipe</li><li>Instaurer un climat de confiance grâce à des conversations honnêtes</li></ul><h3 id="developper-les-signaux-d-39-equipe" tabindex="-1">Développer les signaux d&#39;équipe <a class="header-anchor" href="#developper-les-signaux-d-39-equipe" aria-label="Permalink to &quot;Développer les signaux d&amp;#39;équipe&quot;">​</a></h3><p>Certaines équipes développent un langage abrégé :</p><ul><li>Signaux manuels pour la stratégie</li><li>Des mots de code pour désigner des situations</li><li>Phrases courtes à signification partagée</li></ul><h3 id="controles-reguliers" tabindex="-1">Contrôles réguliers <a class="header-anchor" href="#controles-reguliers" aria-label="Permalink to &quot;Contrôles réguliers&quot;">​</a></h3><p>En dehors des jeux :</p><ul><li>Comment travaillons-nous ensemble ?</li><li>Qu&#39;est-ce qui se passe bien ?</li><li>Que demander de plus ?</li><li>Des problèmes à signaler ?</li></ul><h2 id="le-role-du-capitaine" tabindex="-1">Le rôle du capitaine <a class="header-anchor" href="#le-role-du-capitaine" aria-label="Permalink to &quot;Le rôle du capitaine&quot;">​</a></h2><p>Si votre équipe a un chef désigné :</p><p><strong>Responsabilités du capitaine :</strong></p><ul><li>Décision finale en cas de désaccord au sein de l&#39;équipe</li><li>Donner le ton et l&#39;énergie</li><li>Gérer la dynamique d&#39;équipe</li><li>Rester concentré sous pression</li></ul><p><strong>Tous les autres:</strong></p><ul><li>Partagez votre point de vue</li><li>Soutenir la décision une fois prise</li><li>Contribuer à maintenir l&#39;énergie de l&#39;équipe</li><li>Assumez votre rôle</li></ul><h2 id="points-cles-a-retenir" tabindex="-1">Points clés à retenir <a class="header-anchor" href="#points-cles-a-retenir" aria-label="Permalink to &quot;Points clés à retenir&quot;">​</a></h2><blockquote><p>Les grandes équipes communiquent entre elles, elles ne parlent pas les unes des autres. Elles communiquent avec honnêteté, respect et un engagement commun envers la réussite.</p></blockquote><p>Entraînez-vous à communiquer comme vous vous entraînez à lancer des balles. C&#39;est une compétence qui s&#39;améliore avec l&#39;attention.</p>',68))])}]]);export{c as __pageData,d as default};
